beforeSaveCustomScript:
name = string\trim(string\concatenate(nome, ' ', cognome));
oreMensili = ifThenElse(oreSettimanali != null, number\round(oreSettimanali * 4.33, 2), null);

$today = datetime\today();
$startOk = ifThenElse(dataInizio == null, true, dataInizio <= $today);
$endOk = ifThenElse(dataFine == null, true, dataFine >= $today);
status = ifThenElse($startOk && $endOk, 'Attivo', 'Inattivo');
